int unpack_summary_info(const cdf_stream_t *s, const cdf_header_t *h, cdf_summary_info_header_t *si, cdf_property_info_t **info, size_t *count) {
    int result = -1;
    size_t offset = 0;
    size_t size = 0;

    if (!s || !h || !si || !info || !count) {
        return -1;
    }

    if (h->si_offset >= s->length || h->si_size > s->length - h->si_offset) {
        return -1;
    }

    offset = h->si_offset;
    size = h->si_size;

    if (offset + sizeof(cdf_summary_info_header_t) > s->length) {
        return -1;
    }

    memcpy(si, s->data + offset, sizeof(cdf_summary_info_header_t));
    offset += sizeof(cdf_summary_info_header_t);

    if (si->property_count > SIZE_MAX / sizeof(cdf_property_info_t)) {
        return -1;
    }

    size_t prop_count = si->property_count;
    *info = (cdf_property_info_t *)malloc(prop_count * sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    if (offset + prop_count * sizeof(cdf_property_info_t) > s->length) {
        free(*info);
        *info = NULL;
        return -1;
    }

    memcpy(*info, s->data + offset, prop_count * sizeof(cdf_property_info_t));
    *count = prop_count;
    result = 0;

    return result;
}
